No. When asked to write C++ code, respond with pure C++ code only.

!write, !wb, !build, !ipc are MY tool commands for interacting with the project infrastructure. They are NOT C++ code.

When asked for C++ code:
```cpp
// This is C++ code
auto* cache = GetSubsystem<ResourceCache>();
Node* box = scene_->CreateChild("Box");
auto* model = box->CreateComponent<StaticModel>();
model->SetModel(cache->GetResource<Model>("Models/Box.mdl"));
```

When asked to do a project action:
```
!write path/to/file.cpp
// file content here
!end
```

Don't mix the two. Code questions get code answers. Action requests get tool commands.

A complete game object is a Node with multiple Components:

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// 1. Create the node
Node* enemy = scene_->CreateChild("Enemy");
enemy->SetPosition(Vector3(10.0f, 0.0f, 5.0f));
enemy->SetRotation(Quaternion(0.0f, 180.0f, 0.0f));

// 2. Visual: AnimatedModel for skeletal mesh
auto* animModel = enemy->CreateComponent<AnimatedModel>();
animModel->SetModel(cache->GetResource<Model>("Models/Animals/Fox.mdl"));
animModel->SetCastShadows(true);

// 3. Animation controller
auto* animCtrl = enemy->CreateComponent<AnimationController>();
animCtrl->PlayExclusive("Models/Animals/Fox_AnimalArmatureIdle.ani", 0, true, 0.2f);

// 4. Physics
auto* body = enemy->CreateComponent<RigidBody>();
body->SetMass(1.0f);
body->SetAngularFactor(Vector3::ZERO);  // prevent tipping
auto* shape = enemy->CreateComponent<CollisionShape>();
shape->SetCapsule(0.7f, 1.8f, Vector3(0, 0.9f, 0));

// 5. Custom logic
auto* ai = enemy->CreateComponent<EnemyAI>();
```

Each Component handles one concern. The Node just holds position and parents them together.

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// Create empty scene
scene_ = new Scene(context_);

// Load from XML file
SharedPtr<File> file = cache->GetFile("Scenes/MyScene.xml");
scene_->LoadXML(*file);

// Or load asynchronously
scene_->LoadAsyncXML(file);

// Save a scene to XML
File saveFile(context_, "Scenes/MyScene.xml", FILE_WRITE);
scene_->SaveXML(saveFile);
```

Scene XML contains all nodes, components, and their attributes. When loading, component factories must be registered first (RegisterObject calls in your Start method).

```cpp
// Get all direct children
const Vector<SharedPtr<Node>>& children = parentNode->GetChildren();
for (unsigned i = 0; i < children.Size(); ++i)
{
    Node* child = children[i];
    URHO3D_LOGINFO("Child: " + child->GetName());
}

// Find a specific child by name
Node* found = parentNode->GetChild("ChildName", false);  // false = direct only
Node* deep = parentNode->GetChild("DeepChild", true);     // true = recursive

// Find children with a specific component
PODVector<Node*> lights;
scene_->GetChildrenWithComponent<Light>(lights, true);  // recursive

// Find by tag
PODVector<Node*> enemies;
scene_->GetChildrenWithTag("enemy", enemies, true);
```

Urho3D uses its own Vector, not std::vector. PODVector is for plain-old-data types (pointers, ints, etc).

```cpp
Vector3 a(1.0f, 2.0f, 3.0f);
Vector3 b(4.0f, 5.0f, 6.0f);

// Basic operations
Vector3 sum = a + b;
Vector3 diff = a - b;
Vector3 scaled = a * 2.0f;
float dot = a.DotProduct(b);
Vector3 cross = a.CrossProduct(b);
float len = a.Length();
Vector3 norm = a.Normalized();
float dist = (a - b).Length();

// Useful constants
Vector3::ZERO;     // (0, 0, 0)
Vector3::ONE;      // (1, 1, 1)
Vector3::UP;       // (0, 1, 0)
Vector3::FORWARD;  // (0, 0, 1)
Vector3::RIGHT;    // (1, 0, 0)

// Lerp
Vector3 mid = a.Lerp(b, 0.5f);  // halfway between a and b
```

Urho3D coordinate system: Y is up, Z is forward, X is right. Right-handed.

```cpp
// Create from Euler angles (pitch, yaw, roll in degrees)
Quaternion rot(30.0f, 45.0f, 0.0f);  // pitch=30, yaw=45, roll=0

// Create from axis-angle
Quaternion rot2(90.0f, Vector3::UP);  // 90 degrees around Y axis

// Apply to node
node_->SetRotation(rot);

// Rotate incrementally
node_->Rotate(Quaternion(0.0f, turnSpeed * dt, 0.0f));

// Get forward direction from rotation
Vector3 forward = node_->GetRotation() * Vector3::FORWARD;
Vector3 right = node_->GetRotation() * Vector3::RIGHT;

// Look at a target
node_->LookAt(targetPos);

// Slerp between rotations
Quaternion result = rotA.Slerp(rotB, t);  // t = 0..1

// Identity (no rotation)
Quaternion::IDENTITY;
```

Quaternion * Vector3 rotates the vector. Quaternion * Quaternion combines rotations.

Always use the full module path:

```cpp
// CORRECT — full module paths
#include <Urho3D/Graphics/StaticModel.h>
#include <Urho3D/Graphics/Light.h>
#include <Urho3D/Scene/Scene.h>
#include <Urho3D/Resource/ResourceCache.h>
#include <Urho3D/Physics/RigidBody.h>
#include <Urho3D/Physics/CollisionShape.h>
#include <Urho3D/Input/Input.h>
#include <Urho3D/UI/Text.h>
#include <Urho3D/IO/Log.h>
#include <Urho3D/Core/CoreEvents.h>

// WRONG — never do these
#include "StaticModel.h"     // no bare names
#include "PhysicsWorld.h"    // no bare names
#include <StaticModel.h>     // no bare names
```

Local headers (your own files) use quotes:
```cpp
#include "MyComponent.h"     // your own header
#include "EnemyAI.h"         // your own header
```

Put Urho3D #includes first, then local includes. Add DebugNew last:
```cpp
#include <Urho3D/DebugNew.h>  // always last include
```
